function setSaveStatus(s){cloud.status=s;const el=$('#cloud-status');if(el)el.textContent=s;const dot=$('.save-dot');if(dot)dot.style.background=/Saved to cloud/.test(s)?'#6d9975':/Saving/.test(s)?'#d1aa6f':'#bf8290';}
const cacheKey=name=>`dior_v2_draft_${MEMBERS[name]}`;
const pendingKey=name=>`dior_v2_pending_${MEMBERS[name]}`;
function cacheOwn(){if(!me())return;const entries={};for(const t of CLOUD_TYPES)entries[t]=db[t][me()];try{localStorage.setItem(cacheKey(me()),JSON.stringify(entries));localStorage.setItem(pendingKey(me()),'1');}catch{setSaveStatus('Local save unavailable');}}
function persist(){if(!canEdit())return;cacheOwn();setSaveStatus(navigator.onLine?'Saving…':'Offline — saved locally');clearTimeout(cloud.saveTimer);cloud.saveTimer=setTimeout(flushCloud,850);}
async function flushCloud(){if(!cloud.client||!cloud.user||cloud.writing)return;
 if(!navigator.onLine){setSaveStatus('Offline — saved locally');return;}
 cloud.writing=true;setSaveStatus('Saving…');
 const payload=CLOUD_TYPES.map(t=>({owner_id:cloud.user.id,entry_type:t,entry_key:'all',content:{data:db[t][me()]}}));
 try{const {error}=await cloud.client.from('dior_entries').upsert(payload,{onConflict:'owner_id,entry_type,entry_key'});if(error)throw error;
 localStorage.removeItem(pendingKey(me()));setSaveStatus('Saved to cloud');}
 catch(e){console.warn('Cloud save error',e);setSaveStatus('Unable to sync — draft saved locally');}
 finally{cloud.writing=false;}
}
async function loadCloud(){if(!cloud.client||!cloud.user)return;
 setSaveStatus('Loading saved work…');
 const {data,error}=await cloud.client.from('dior_entries').select('owner_id,entry_type,content,updated_at');
 if(error){setSaveStatus('Cloud unavailable — local draft only');console.warn(error);const backup=localStorage.getItem(cacheKey(me()));if(backup){try{const draft=JSON.parse(backup);for(const t of CLOUD_TYPES)if(draft[t])db[t][me()]=draft[t];}catch{}}refresh();return;}
 db=emptyDB();
 for(const row of data||[]){const person=Object.keys(MEMBERS).find(n=>MEMBERS[n]===row.owner_id);if(person&&CLOUD_TYPES.includes(row.entry_type))db[row.entry_type][person]=row.content?.data??(row.entry_type==='answers'||row.entry_type==='practice'?{}:[]);}
 const ownCache=localStorage.getItem(cacheKey(me()));
 if(localStorage.getItem(pendingKey(me()))==='1'&&ownCache){try{const draft=JSON.parse(ownCache);for(const t of CLOUD_TYPES)if(draft[t])db[t][me()]=draft[t];setSaveStatus('Unsynced draft recovered — syncing');setTimeout(flushCloud,100);}catch{}}
 else setSaveStatus('Saved to cloud');
 ui.person=me();const draftMock=db.mocks[me()]?.[0];if(draftMock&&!draftMock.finished)ui.mock=draftMock;refresh();
}
function authModal(show){$('#auth-modal')?.classList.toggle('hide',!show);if(show)setTimeout(()=>$('#auth-email')?.focus(),10);}
function authNotice(){return `<div class="card auth-notice"><img class="motif motif-medium" src="dior-motif.jpg" alt=""><h3>Your answers, in one place.</h3><p>Sign in as Eli or Habibti to use your cloud-saved journals, answers and scores on any device.</p><button class="btn" data-action="show-login">Sign in</button></div>`;}
async function initCloud(){
 if(!window.supabase?.createClient){setSaveStatus('Cloud library unavailable — check connection');return;}
 cloud.client=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true}});
 const {data:{session}}=await cloud.client.auth.getSession();await handleSession(session);
 cloud.client.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>handleSession(session),0);});
}
async function handleSession(session){
 if(!session?.user){cloud.user=null;cloud.person=null;db=emptyDB();setSaveStatus('Sign in to cloud save');updateAuthUI();refresh();return;}
 const name=Object.keys(MEMBERS).find(k=>MEMBERS[k]===session.user.id);
 if(!name){await cloud.client.auth.signOut();setSaveStatus('This account is not approved');return;}
 if(cloud.user?.id===session.user.id&&cloud.ready)return;
 cloud.user=session.user;cloud.person=name;cloud.ready=true;updateAuthUI();await loadCloud();
}
function updateAuthUI(){const b=$('#auth-toggle');if(b)b.textContent=me()?`${me()} · Sign out`:'Sign in';}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>el.classList.remove('show'),2400);}
