let timer={seconds:0,total:0,running:false,interval:null,phase:'ready',read:0,speak:300,used:0,warnings:true};
function resetTimer(){clearInterval(timer.interval);timer={seconds:0,total:0,running:false,interval:null,phase:'ready',read:0,speak:300,used:0,warnings:true};}
function formatTime(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(Math.max(0,sec)%60).padStart(2,'0')}`;}
function repaintTimers(){
 $$('.js-timer-time').forEach(el=>el.textContent=formatTime(timer.total?timer.seconds:Number(el.closest('.js-timer-panel')?.dataset.preset||300)));
 $$('.js-timer-progress').forEach(el=>el.style.width=`${timer.total?100*timer.seconds/timer.total:100}%`);
 $$('.js-timer-state').forEach(el=>el.textContent=timer.phase==='read'?'READING / PREPARING':timer.phase==='speak'?'SPEAKING / ANSWERING':timer.phase==='done'?'TIME COMPLETED':'READY TO START');
 $$('.js-timer-panel').forEach(el=>el.classList.toggle('urgent',timer.seconds<=30&&timer.seconds>0));
 $$('.timer-used').forEach(el=>{if(timer.phase==='done')el.textContent=`Time used: ${formatTime(timer.used)} of ${formatTime(timer.speak+timer.read)}. Reflect on clarity as well as pace.`;});
}
function timerSet(sec,read=0){clearInterval(timer.interval);timer={seconds:read||sec,total:read||sec,running:false,interval:null,phase:read?'read':'speak',read,speak:sec,used:0,warnings:true};repaintTimers();}
function timerStart(){if(timer.running)return;if(timer.phase==='ready'||timer.phase==='done'){const panel=$('.js-timer-panel');timerSet(Number(panel?.dataset.preset||300),Number(panel?.dataset.read||0));}
 timer.running=true;timer.interval=setInterval(()=>{
 timer.seconds=Math.max(0,timer.seconds-1);timer.used++;
 if(timer.seconds===60||timer.seconds===30){const el=$('#timer-warning');if(el)el.textContent=`${timer.seconds} seconds remaining in ${timer.phase==='read'?'reading':'answering'} phase`;
 if($('#warning-toggle')?.checked&&typeof AudioContext!=='undefined'){try{const context=new AudioContext();const oscillator=context.createOscillator(),gain=context.createGain();oscillator.connect(gain);gain.connect(context.destination);oscillator.frequency.value=700;gain.gain.value=.03;oscillator.start();oscillator.stop(context.currentTime+.1);setTimeout(()=>context.close(),300);}catch{}}}
 if(timer.seconds===0){if(timer.phase==='read'){timer.phase='speak';timer.seconds=timer.speak;timer.total=timer.speak;toast('Reading time ended — begin answering.');}
 else{timerPause();timer.phase='done';toast('Station finished. Check your answer.');}}
 repaintTimers();},1000);repaintTimers();}
function timerPause(){clearInterval(timer.interval);timer.interval=null;timer.running=false;repaintTimers();}
const timerBox=(preset=300,read=60)=>`<div class="timer-panel js-timer-panel" data-preset="${preset}" data-read="${read}"><div class="mini js-timer-state">READY TO START</div><div class="countdown js-timer-time">${formatTime(read||preset)}</div><div class="progress-rail"><div class="progress-fill js-timer-progress" style="width:100%"></div></div><p class="micro">Reading: ${formatTime(read)} · Speaking: ${formatTime(preset)}</p><div class="actions"><button class="btn sm" data-action="timer-go">▶ Start</button><button class="btn secondary sm" data-action="timer-pause">Pause</button><button class="btn ghost sm" data-action="timer-reset" data-secs="${preset}" data-read="${read}">Reset</button></div><label class="micro"><input id="warning-toggle" type="checkbox"> Sound at 60s and 30s remaining</label><p class="micro" id="timer-warning" aria-live="polite"></p><p class="micro timer-used"></p></div>`;

