const dayPlan=[
 ['Day 1','Motivation + audit','Write bullet points for why medicine, why doctor and why this university. Give two 90-second answers aloud.','Ask each other the two questions; challenge one vague claim each.'],
 ['Day 2','Reflection bank','Prepare three genuine experiences using STARR, with a clear learning point.','Swap one experience each; ask “what did you actually learn?”'],
 ['Day 3','Ethics foundations','Learn four principles, consent, capacity and confidentiality.','Debate two cases; each person argues both sides before concluding.'],
 ['Day 4','Professional judgement','Learn GMC four domains, safeguarding, candour and raising concerns.','Role-play a confidentiality or professionalism scenario.'],
 ['Day 5','NHS essentials','Learn six NHS values, MDT roles and patient pathways.','Test each other on values with concrete examples.'],
 ['Day 6','Healthcare issues','Know 10 Year Health Plan, waits and AI: issue, patient impact, trade-off.','Choose a news issue; give each other one follow-up challenge.'],
 ['Day 7','First full mock','Complete six mixed stations under timed conditions. Identify top two weaknesses.','Run a six-station mock with scoring and specific feedback.'],
 ['Day 8','Communication','Practise open questions, checking understanding and not overpromising.','Do two role-plays, then swap roles and reflect.'],
 ['Day 9','Teamwork + resilience','Prepare teamwork, leadership, mistake and feedback examples.','Ask unexpected follow-ups to test natural answers.'],
 ['Day 10','Practical stations','Do no-calculator percentages and one data task; revisit weaker ethics.','Complete practical challenges and explain the reasoning out loud.'],
 ['Day 11','University deep dive','Know format, course features and personal “why here”; check invitation.','Run university-style stations and probe course knowledge.'],
 ['Day 12','Second full mock','Complete another circuit without notes; score using the same rubric.','Compare with Day 7 and fix the weakest station type.'],
 ['Day 13','Targeted polish','Do 3–4 weak stations, not a whole new textbook of notes.','Short tough-question drill and constructive feedback.'],
 ['Day 14','Stay fresh','Review brief prompts, check documents and travel/online tech; stop heavy studying.','One gentle warm-up only if useful; prioritise rest.']
];
