 personal:[['Direct response',6,'Answer the exact question without detouring.'],['Specific evidence',9,'Use an authentic example with your own actions.'],['Insight and reflection',9,'Explain what you learned and what changed.'],['Clarity and professionalism',6,'Organise the answer naturally and respectfully.']],
 nhs:[['Accurate explanation',9,'Define the actual NHS issue without unsupported claims.'],['Patient and team impact',7,'Consider patient care, staff and inequalities.'],['Balanced reasoning',8,'Compare solutions with limitations and trade-offs.'],['Clear conclusion',6,'Give a measured and practical view.']]
