function classify(prompt,tag=''){const v=(prompt+' '+tag).toLowerCase();if(/calculate|how many|percentage|%|ratio|graph|table|median|risk reduction|sensitivity|specificity|waiting list had|numeracy|data interpret/.test(v))return 'practical';if(/role.play|reassure|angry|upset|explain .* to|person feels|friend is|visitor|communication/.test(v))return 'roleplay';if(/ethic|patient refus|consent|confidential|capacity|safeguard|colleague|mistake|unprofessional|medical error|dilemma|fair allocation/.test(v))return 'ethics';if(/nhs|ai |healthcare system|health inequalities|waiting time|workforce|funding/.test(v))return 'nhs';return 'personal';}
function modelPrompt(q,kind,guide){const p=q.toLowerCase();if(kind==='practical')return guide||'Identify the relevant numbers, show the calculation, state units and check that the result makes sense. Explain what your result cannot tell us.';
 if(kind==='ethics'){if(/refus/.test(p))return 'I would first understand why the person is considering refusing treatment and check they have enough information and decision-making capacity. I would explain the options neutrally, respect a capacitous adult’s decision and ask the supervising clinician for appropriate support. The tension is between avoiding harm and respecting autonomy.';
 if(/confidential|record|privacy/.test(p))return 'I would not access or disclose confidential information without a legitimate reason. I would listen to the concern, explain the boundary without judgement and direct the person to an authorised route. If there is a serious safeguarding concern, I would seek prompt senior advice about proportionate information-sharing.';
 if(/mistake|error/.test(p))return 'I would prioritise the patient’s safety, check the facts and raise the concern promptly with an appropriate supervisor. I would be open and honest through the proper process, avoid blaming individuals before understanding what happened and reflect on how errors can be prevented.';
 return 'I would identify the competing responsibilities, gather relevant facts and listen to the people affected. I would apply the ethical principles that genuinely matter, consider risks and alternatives, and seek senior guidance where decisions exceed my role. I would explain my reasoning respectfully without pretending there is a simple universal answer.';}
 if(kind==='roleplay')return '“Thanks for telling me. I can understand why that feels upsetting. Could you tell me what you were expecting and what happened?” I would listen without interrupting, reflect back the key concern, explain only what I know within my role, seek an appropriate colleague if needed, and check whether the proposed next step addresses the concern.';
 if(/why .*university|why .*leicester|why .*nottingham|why .*leeds|why .*keele|why .*liverpool|why .*plymouth|why this medical school/.test(p))return (uniDeep[ui.uni]?.why||'Choose two verified course features and explain how they suit your learning style, experience and values.');
 if(/why medicine|why.*doctor|medicine rather|nursing/.test(p))return 'My interest in medicine combines learning how disease affects people with the responsibility of helping patients make informed decisions. Experiences I have genuinely had helped me see how teamwork, clear communication and ongoing learning matter. I respect the different expertise of nurses and other professionals; the combination of diagnostic reasoning, medical responsibility and long-term study is what particularly draws me to a doctor’s role.';
 if(/strength|weakness/.test(p))return 'For a strength, I would choose one that I can show in a true situation: for example, listening carefully when a group member was overlooked, changing the plan so everyone could contribute, and noticing a better outcome. For a weakness, I would name a genuine manageable limitation, describe steps I am taking and give evidence of progress rather than claiming I have solved it.';
 if(/team|leadership|conflict|disagree/.test(p))return 'During a group task, there was uncertainty about who was responsible for an urgent part of the work. I suggested dividing the tasks based on availability, checked everyone understood the plan and followed up before the deadline. We finished the task and I learned that calm clarification prevents small issues becoming conflict. This is an illustrative example; use your own experience.';
 if(/work experience|volunteer|observ/.test(p))return 'An experience supporting others showed me that effective care is not simply doing tasks quickly. I noticed how listening and explaining what would happen reduced uncertainty. I would discuss exactly what I observed, my own role and how it changed my understanding of compassionate, team-based care. I would never claim to have carried out clinical tasks I did not do.';
 if(/feedback|mistake|fail|resilien|pressure/.test(p))return 'When I received feedback on an assignment, I initially realised that I had misunderstood the expectations. I asked for specific examples, practised the weaker skill and checked whether the changes worked. The outcome was a more considered approach. I learned that admitting gaps early and acting on feedback is important in demanding professional training.';
 if(kind==='nhs')return 'I would define the issue with one reliable fact, explain what it means to patients and staff, and compare two realistic responses. For example, additional capacity may reduce delays while prevention and stronger community care address avoidable demand; both take resources and time. I would avoid making promises about a policy without examining its effects.';
 return 'I would start with a brief, truthful situation, describe the action I personally took, explain the outcome and finish with what I learned. I would connect that reflection to a relevant quality in medicine, without claiming experience or responsibilities I have not had.';
}
function markingGuide(prompt,guide='',type=''){const k=type||classify(prompt);const profile=markProfiles[k]||markProfiles.personal;const keyPoint=guide||'Explain your reasoning using a genuine example or the relevant professional and ethical principles.';return `<details class="accordion marksheet"><summary>Full practice mark scheme · 30 marks</summary><div class="acc-body"><p class="micro"><b>Practice only:</b> not an official medical school rubric. Each criterion is tailored to this station type; award only points actually demonstrated.</p><div class="mark-grid">${profile.map((x,i)=>`<div class="mark-row"><strong>${esc(x[0])} · ${x[1]} marks</strong><p>${esc(x[2])}</p><div class="micro">Excellent: clear and complete · Good: mostly covered · Average: partial or vague · Weak: absent, unsafe or contradictory.</div></div>`).join('')}</div><h4>Key points for this question</h4><p>${esc(keyPoint)}</p><h4>Illustrative strong response</h4><p>${esc(modelPrompt(prompt,k,guide))}</p><h4>Common mistakes</h4><p>${k==='practical'?'Using irrelevant figures, losing units, skipping steps or claiming causation from correlation.':k==='ethics'?'Listing principles without application, guessing clinical law, ignoring the patient or acting beyond competence.':k==='roleplay'?'Interrupting, jargon, false reassurance or giving a promise you cannot keep.':k==='nhs'?'Quoting figures without sources, ignoring the patient impact or presenting only one side.':'Overly generic examples, no personal action, no reflection or a memorised speech.'}</p></div></details>`;}
function practiceEditor(key,q,kind,guide){const item=db.practice[ui.person][key]||{};const editable=canEdit();return `<div class="card practice-editor"><div class="flex-between"><h3>Write or plan your response</h3><span class="tag ${editable?'success':'muted'}">${editable?'Cloud autosave':'View only / sign in'}</span></div><p class="micro">Your notes are private to your account for editing, but both approved accounts can read each other's work.</p><textarea class="input" data-action="practice-write" data-key="${esc(key)}" ${!editable?'disabled':''} placeholder="Key points, reasoning, reflection…">${esc(item.answer||'')}</textarea><div class="flex-between"><span class="micro" id="practice-status">${editable?'Saves automatically when connected':'Sign in as the owner to edit'}</span><button class="btn sm secondary" type="button" data-action="practice-score-open" data-key="${esc(key)}">Mark this attempt</button></div><div class="score-editor" id="score-box-${encodeURIComponent(key)}" hidden></div></div>${markingGuide(q,guide,kind)}`;}
function scoreInterface(key,q,kind){const profile=markProfiles[kind]||markProfiles.personal;return `<h4>Partner / self-marking rubric</h4><p class="micro">This score is entered by a person, not AI. Tick only what you can point to in the response. Do not grade by keywords alone.</p><div class="score-grid">${profile.map((c,i)=>`<div class="field"><label>${esc(c[0])} (0–${c[1]})</label><select class="input score-criterion" data-max="${c[1]}">${Array.from({length:c[1]+1},(_,n)=>`<option value="${n}" ${n===0?'selected':''}>${n} / ${c[1]}</option>`).join('')}</select></div>`).join('')}</div><div class="field"><label>What worked? Be specific.</label><textarea id="mark-strength" class="input" rows="2"></textarea></div><div class="field"><label>What was missing and what will you do differently?</label><textarea id="mark-improve" class="input" rows="2"></textarea></div><button class="btn" data-action="practice-score-save" data-key="${esc(key)}" data-kind="${kind}">Save rubric & feedback</button>`;}

function renderUniversities(){const u=unis[ui.uni],d=uniDeep[ui.uni],clock=uniTiming[ui.uni];return `${pageHead(2,'University-specific preparation','Six universities. Official interview facts are separated from suggested practice.')}
 <div class="tabbar">${Object.keys(unis).map(name=>`<button data-action="uni" data-uni="${name}" class="${ui.uni===name?'active':''}">${name}</button>`).join('')}</div>
 <div class="hero-small"><div class="flex-between"><div><div class="kicker">2027 ENTRY / ${ui.uni.toUpperCase()}</div><h2>${ui.uni} Medicine</h2><p class="subtle" style="margin:0">Your interview invitation is always the final authority.</p></div><img class="motif motif-medium" src="dior-motif.jpg" alt=""></div></div>
 <div class="grid three" style="margin:16px 0"><div class="card"><div class="kicker">PUBLISHED FORMAT</div><p>${u.format}</p></div><div class="card"><div class="kicker">DELIVERY</div><p>${u.delivery}</p></div><div class="card"><div class="kicker">DATES</div><p>${u.dates}</p></div></div>
 ${timingLabel(clock)}
 ${section('Why this medical school?','Look for a course feature you can genuinely connect to your interests.')}
 <div class="grid two"><article class="card"><h3>What makes it worth exploring</h3>${listItems(d.fit)}<div class="divider"></div><p class="small"><b>Research:</b> ${d.research}</p><p class="small"><b>Student support and societies:</b> ${d.support}</p><p class="small"><b>Community:</b> ${d.community}</p></article><article class="card pink"><h3>Example: “Why ${ui.uni}?”</h3><p>${d.why}</p><p class="micro">Example only. Research current module descriptions and replace generic claims with your genuine experiences.</p><h4>What the interview assesses</h4>${listItems(u.focus)}<p class="small"><b>Preparation strategy:</b> ${u.strategy}</p></article></div>
 ${section('10 tailored practice questions','Original practice prompts — NOT verified past interview stations.')}
 <div class="grid two">${u.questions.map((q,i)=>`<article class="card"><div class="kicker">${ui.uni} · QUESTION ${String(i+1).padStart(2,'0')}</div><h4>${esc(q)}</h4><div class="micro">${clock.official?'Official format reference; suggested question':'Suggested practice timing and question'}</div><div class="actions"><button class="btn sm secondary" data-action="uni-to-timed" data-q="${i}">Practise this question →</button></div>${markingGuide(q,`What evidence would you use for this ${ui.uni} interview theme? ${u.focus[i%u.focus.length]}.` )}</article>`).join('')}</div>
 <div class="note"><b>Sources:</b> University pages confirm the interview details; the questions here are newly written. TheUKCATPeople has a larger independently written practice bank, not an authenticated archive of past stations.</div>${sourceBox([[official[ui.uni],`${ui.uni} official course/admissions`],[ukcat[ui.uni],`TheUKCATPeople practice bank`],['https://www.theukcatpeople.co.uk/application-guide/interview','All medical school interview guides']])}`;}

function renderStructures(){const set=[
 ['STARR','Personal experience and reflection','Situation → Task → Action → Result → Reflection','Tell me about a time you managed disagreement.','“In our group project, two people disagreed about priorities. I asked each to explain their concern, suggested we rank the tasks by deadline and checked we all agreed. We finished on time. I learned to address tension early rather than hope it disappears.”','Spending most of the answer describing the situation; forgetting what you personally did.'],
 ['SPIES','Professional concerns and difficult situations','Seek information → Patient safety → Initiative → Escalate → Support','You notice a colleague repeatedly skipping a safety check.','“I would confirm what I had seen without accusing anyone. If a patient could be at risk, I would alert an appropriate supervisor promptly, document concerns through the right process and support a culture where staff can raise issues safely.”','Confronting someone aggressively, assuming facts or handling a safety concern alone.'],
 ['Four pillars','Ethical dilemmas','Autonomy → Beneficence → Non-maleficence → Justice','A capacitous adult refuses a recommended treatment.','“I would explore why they want to refuse, check they understand the likely benefits and risks, and ensure their decision is voluntary. A capacitous adult can usually refuse treatment even if clinicians disagree; I would respect the decision and seek senior guidance.”','Reciting all four pillars without explaining which ones matter in this situation.'],
 ['CAMP','Understanding a doctor’s career and motivation','Clinical → Academic → Management → Personal','What attracts you to the varied role of a doctor?','“The clinical responsibility and long-term patient relationships interest me, alongside continuing to learn from evidence. I also like that doctors work within teams to improve services. I know the workload and emotional pressures can be demanding.”','Implying doctors work alone or nursing is a lesser career.'],
 ['Communication','Role-play and sensitive conversations','Listen → Acknowledge → Clarify → Explain → Check','A visitor is frustrated about a delay.','“I can see this has been frustrating. Could you tell me what happened? I will listen, explain what I can within my role and ask the appropriate team member for a realistic update. Have I understood your concern correctly?”','False reassurance, interrupting, jargon and overpromising.']
 ];return `${pageHead(3,'Mastering MMI answer structures','Five flexible frameworks. Pick the one that helps you think clearly rather than reciting it.')}
 <div class="grid two">${set.map((s,i)=>`<article class="card"><span class="card-label">FRAMEWORK 0${i+1}</span><h3>${s[0]}</h3><div class="micro"><b>Use it for:</b> ${s[1]}</div><p class="boxline" style="margin:12px 0">${s[2]}</p><p class="small"><b>Example question:</b> ${s[3]}</p>${accordion('Example answer',`<p>${esc(s[4])}</p>`)}<p class="micro"><b>Avoid:</b> ${s[5]}</p></article>`).join('')}</div><div class="note">These are structures, not scripts. Personalise every answer with genuine evidence and reflection.</div>`;}

function commonList(){let ids=questions.map((q,i)=>i).filter(i=>ui.category==='All'||questions[i].category===ui.category).filter(i=>questions[i].q.toLowerCase().includes(ui.search.toLowerCase()));return ids.length?ids.map(i=>`<button class="question-button ${ui.q===i?'active':''}" data-action="question" data-q="${i}"><span>${esc(questions[i].q)}</span><span class="q-num">${db.answers[ui.person][i]?.trim()?'✓':String(i+1).padStart(2,'0')}</span></button>`).join(''):`<div class="empty">No matching questions.</div>`;}
function renderCommon(){let q=questions[ui.q],filled=Object.values(db.answers[ui.person]).filter(s=>String(s).trim()).length;return `${pageHead(4,'Preparing common MMI answers','The classic questions come up in different forms everywhere. Prepare your own bullet-point ideas and practise them aloud.')}
 <div class="grid three" style="margin-bottom:16px"><div class="card soft"><div class="stat">${questions.length}</div><p>High-yield practice questions, organised by theme.</p></div><div class="card"><div class="stat">${filled}</div><p>Answers started by ${ui.person}, synced through Supabase.</p></div><div class="card"><div class="kicker">HOW TO USE THIS</div><p>Write key points and a genuine example. Then shut the notes and speak for 90–120 seconds.</p></div></div>
 <div class="split"><aside class="card sidebar-card"><div class="field" style="margin-bottom:10px"><label>Question category</label><select class="input" data-action="category"><option>All</option>${questionGroups.map(g=>`<option ${ui.category===g.name?'selected':''}>${g.name}</option>`).join('')}</select></div><div class="field" style="margin-bottom:12px"><label>Search</label><input class="input" data-action="common-search" placeholder="Find a question..." value="${esc(ui.search)}"></div><div class="question-list" id="common-list">${commonList()}</div></aside>
 <div class="stack"><div class="card"><div class="flex-between"><div class="kicker">YOUR ANSWER BANK</div>${personPick()}</div><div class="divider"></div><div class="card-label">${esc(q.category)}</div><h2 style="font-size:29px">${esc(q.q)}</h2><p class="micro">Aim: 90–120 seconds spoken. Use bullet points here, not a polished script.</p><textarea class="input answer-editor" id="common-answer" data-action="answer-input" data-q="${ui.q}" placeholder="Your own evidence, key points and reflection...">${esc(db.answers[ui.person][ui.q]||'')}</textarea><div class="flex-between" style="margin-top:9px"><span class="live" id="answer-status">Cloud autosave · sign in required</span><button class="btn secondary sm" data-action="common-timer">Practise aloud ↗</button></div></div>
 <details class="accordion"><summary>What a strong answer needs</summary><div class="acc-body"><p>${esc(q.guide)}</p><p><strong>Check yourself:</strong> Did you answer the actual question, give specific evidence and say what you learned?</p></div></details>${markingGuide(q.q,q.guide)}
 <div class="note"><strong>Shared reading, separate editing:</strong> Sign in to save automatically to Supabase. Both approved accounts can read each other's answers; only the owner can change them.</div></div></div>`;}
function renderReflections(){let arr=db.reflections[ui.person];let edit=arr.find(e=>e.id===ui.editingReflection)||{};return `${pageHead(5,'Personal experience & reflection bank','The strongest answers come from experiences you can actually talk about. Save what happened, what you did and what changed.')}
 <div class="flex-between" style="margin-bottom:17px"><div class="kicker">CHOOSE YOUR PERSONAL JOURNAL</div>${personPick()}</div>
 <div class="grid two"><div class="card"><h3>${edit.id?'Edit experience':'Add an experience'}</h3><form id="reflection-form"><input type="hidden" name="id" value="${esc(edit.id||'')}"><div class="field"><label>Short title</label><input name="title" required maxlength="100" value="${esc(edit.title||'')}" placeholder="e.g. Helping at a community event"></div><div class="field" style="margin-top:10px"><label>Category</label><select name="type" class="input">${['Work experience','Volunteering','Empathy','Teamwork','Leadership','Resilience','Mistake / feedback','Other'].map(x=>`<option ${edit.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:10px"><label>Situation — what was happening?</label><textarea name="situation" class="input" rows="2" required>${esc(edit.situation||'')}</textarea></div><div class="field" style="margin-top:10px"><label>Action — what did YOU do?</label><textarea name="action" class="input" rows="2" required>${esc(edit.action||'')}</textarea></div><div class="field" style="margin-top:10px"><label>Result — what happened?</label><textarea name="result" class="input" rows="2">${esc(edit.result||'')}</textarea></div><div class="field" style="margin-top:10px"><label>Reflection — what changed / how is this relevant to medicine?</label><textarea name="reflection" class="input" rows="3" required>${esc(edit.reflection||'')}</textarea></div><div class="actions"><button class="btn" type="submit">Save reflection</button>${edit.id?'<button type="button" class="btn secondary" data-action="reflection-cancel">Cancel edit</button>':''}</div></form></div>
 <div class="card"><div class="flex-between"><h3>${ui.person}'s reflection bank</h3><span class="count-badge">${arr.length} saved</span></div><p class="micro">Use details, but never include real patient names or other identifying information.</p><div class="list-rows">${arr.length?arr.slice().reverse().map(e=>`<div class="entry-card"><div class="flex-between"><div><div class="meta">${esc(e.type)} · ${fmtDate(e.date)}</div><h4>${esc(e.title)}</h4></div><div class="actions"><button class="btn ghost sm" data-action="reflection-edit" data-id="${esc(e.id)}">Edit</button><button class="btn ghost sm" data-action="reflection-delete" data-id="${esc(e.id)}">Delete</button></div></div>${accordion('Read full STARR reflection',`<p><b>Situation:</b> ${rich(e.situation)}</p><p><b>Action:</b> ${rich(e.action)}</p><p><b>Result:</b> ${rich(e.result)}</p><p><b>Reflection:</b> ${rich(e.reflection)}</p>`)}</div>`).join(''):`<div class="empty"><img class="motif motif-small" src="dior-motif.jpg" alt="">Your first reflection starts here.<br>Pick one real experience and write what it taught you.</div>`}</div></div></div>`;}
function renderEthics(){const e=dilemmas[ui.ethic];const q=e[0],g=e[1];return `${pageHead(6,'Medical ethics, professionalism & dilemmas','Think through the person, the competing duties and the safest justified next step.')}
 ${section('The four ethical pillars','The ethical pillars are different from the four GMC domains.')}
 <div class="grid four">${principles.map((a,i)=>`<div class="card"><div class="float-number">0${i+1}</div><h4>${a[0]}</h4><p class="small">${a[1]}</p></div>`).join('')}</div>
 ${section('A six-step ethical response')}
 <div class="grid three">${[['01','Identify the conflict','Name the duties or values that pull in different directions.'],['02','Apply relevant pillars','Explain which principles matter here and why.'],['03','Consider perspectives','Patient, family, staff and community where relevant.'],['04','Compare options','Benefits, harms, rights, constraints and missing facts.'],['05','Justify a safe decision','Explain what you would do and when to seek senior help.'],['06','Reflect','Acknowledge uncertainty and what could change your view.']].map(x=>`<article class="card"><span class="card-label">STEP ${x[0]}</span><h4>${x[1]}</h4><p class="small">${x[2]}</p></article>`).join('')}</div>
 ${section('Four GMC professional domains')}
 <div class="grid two">${[['Knowledge, skills & development','Competence, improvement, evidence and recognising your limits.'],['Patients, partnership & communication','Respect, informed decisions, safeguarding and compassion.'],['Colleagues, culture & safety','Teamwork, safety concerns and respectful workplace behaviour.'],['Trust & professionalism','Honesty, boundaries, integrity and accountability.']].map(x=>`<div class="card"><h4>${x[0]}</h4><p>${x[1]}</p></div>`).join('')}</div>
 ${section('Essential ethical and professional topics')}
 <div class="grid two">${ethicTopics.map(a=>`<div class="card"><h4>${a[0]}</h4><p class="small">${a[1]}</p></div>`).join('')}</div>
 ${section('Ethical scenario workshop','Choose one case; reason out loud before checking the marking guidance.')}
 <div class="split"><aside class="card sidebar-card"><div class="question-list">${dilemmas.map((x,i)=>`<button class="question-button ${ui.ethic===i?'active':''}" data-action="ethic-select" data-i="${i}">${esc(x[0])}</button>`).join('')}</div></aside><div class="stack"><div class="card"><div class="kicker">ETHICAL SCENARIO ${ui.ethic+1}/${dilemmas.length}</div><h2 style="font-size:26px">${esc(q)}</h2>${timingLabel(practiceClock())}${timerBox(300,60)}<details class="accordion" style="margin-top:15px"><summary>Six-step examiner guidance</summary><div class="acc-body"><p><b>Central conflict:</b> ${esc(q)}</p><p><b>Relevant principles:</b> Focus on autonomy, avoidance of harm, fairness and professional duties only where applicable. Do not list them mechanically.</p><p><b>Perspectives:</b> Ask what the patient, family and professionals know and value; recognise gaps in the facts.</p><p><b>Options and safe response:</b> ${esc(g)}</p><p><b>Reflection:</b> Say what uncertainty remains, and what senior advice or new information could change the outcome.</p></div></details></div>${practiceEditor('ethics-'+ui.ethic,q,'ethics',g)}</div></div>
 <div class="note">Applicants are not being asked to practise medicine independently. Discuss principles, communication and appropriate escalation.</div>
 ${sourceBox([['https://www.gmc-uk.org/professional-standards/the-professional-standards/good-medical-practice/','GMC Good medical practice'],['https://www.gmc-uk.org/professional-standards/the-professional-standards/decision-making-and-consent','GMC consent guidance']])}`;}

function renderNHS(){return `${pageHead(7,'NHS values & healthcare knowledge','Learn the things interviewers actually expect you to discuss: values, how care works and the pressures that shape patient experience.')}
 <div class="note"><strong>Important distinction:</strong> The <strong>six NHS values</strong> are not the same as the <strong>four ethical principles</strong> (autonomy, beneficence, non-maleficence, justice). The four principles are covered in Ethics.</div>
 ${section('The six NHS Constitution values')}
 <div class="grid three">${nhsValues.map((x,i)=>`<div class="card"><div class="float-number">${String(i+1).padStart(2,'0')}</div><h4>${x[0]}</h4><p class="small">${x[1]}</p></div>`).join('')}</div>
 ${section('How care is organised','An interview-level overview — England-focused.')}
 <div class="grid two">${[
 ['Primary care','First contact: GPs, community pharmacies, dentistry and optometry. Often supports prevention, monitoring and referral.'],
 ['Secondary care','Specialist or hospital care, usually following a referral, including outpatient and inpatient services.'],
 ['Tertiary care','Highly specialist services, often serving a wider region, such as complex procedures or rare conditions.'],
 ['Integrated care systems / ICBs','Local NHS and partner organisations plan joined-up services. Integrated Care Boards oversee much NHS planning and commissioning locally in England.'],
 ['NICE','Evaluates evidence and provides guidance on effective, cost-conscious care and technologies in England.'],
 ['CQC','Independent regulator inspecting and rating health and adult social care services in England.'],
 ['GMC','Regulates doctors and medical professional standards; Good medical practice outlines expected conduct.'],
 ['The multidisciplinary team','Doctors work alongside nurses, pharmacists, physiotherapists, therapists, paramedics, social workers and many more. Safe care depends on clear roles and collaboration.']
 ].map(x=>`<div class="card"><h4>${x[0]}</h4><p class="small">${x[1]}</p></div>`).join('')}</div>
 ${section('The NHS problems worth understanding')}
 <div class="grid three">${[
 ['Waiting times','Patient impact: pain, anxiety and delayed treatment. Consider demand, capacity, diagnostics and prioritisation.'],
 ['Workforce & wellbeing','Staffing, retention and supportive training affect safety, continuity and morale.'],
 ['Health inequalities','Housing, income, language, geography and disability influence access and outcomes.'],
 ['Ageing & long-term conditions','More complex needs mean greater importance for continuity, prevention and community care.'],
 ['Funding & opportunity cost','Every spending decision has alternatives; fairness, evidence and population benefit matter.'],
 ['Digital health & AI','Digital tools may improve access and efficiency but require privacy, accessibility and safety checks.']
 ].map(x=>`<div class="card soft"><h4>${x[0]}</h4><p class="small">${x[1]}</p></div>`).join('')}</div>
 ${section('Three interview-ready explanations')}
 ${accordion('What does patient-centred care actually mean?','Ask about individual needs and preferences; explain risks and options; support shared decisions; respect dignity and individual circumstances.',true)}
 ${accordion('What is clinical governance?','The systems used to improve quality and safety: standards, audit, incident reporting, learning, training and accountability.')}
 ${accordion('Why are prevention and public health important?','Preventing illness can improve outcomes and reduce future demand, but benefits depend on equity, evidence, access and long-term investment.')}
 ${sourceBox([['https://www.gov.uk/government/publications/the-nhs-constitution-for-england/the-nhs-constitution-for-england','NHS Constitution'],['https://www.gov.uk/government/collections/10-year-health-plan-for-england','10 Year Health Plan'],['https://www.gmc-uk.org/professional-standards/the-professional-standards/good-medical-practice/','GMC professional standards']])}`;}
function renderNews(){return `${pageHead(8,'Recent medical news & debates','Six issues worth knowing for 2027 interviews. Learn the patient impact and the arguments on both sides, not a list of headlines.')}
 <div class="note"><strong>Research snapshot: 15 November 2026.</strong> These are hand-checked topics, not a live news feed. Re-check sources just before your interview. For a strong answer: <strong>issue → impact → options → your view</strong>.</div>
 <div class="grid two" style="margin-top:17px">${news.map((x,i)=>`<div class="card"><div class="card-label">${x.date}</div><h3>${x.title}</h3><p>${x.detail}</p><div class="boxline small" style="margin:14px 0"><strong>Why it matters:</strong> ${x.why}</div><p class="small"><strong>Question to debate:</strong> ${x.debate}</p><div class="source-box">${link(x.source,x.label)}</div></div>`).join('')}</div>
 ${section('How to talk about news in 60 seconds')}
 <div class="grid four">${[['01','State the issue','One accurate sentence and a source.'],['02','Patient impact','Who is affected, and how?'],['03','Trade-off','Give at least one benefit and limitation.'],['04','Your view','Offer a cautious, workable conclusion.']].map(x=>`<div class="card"><div class="float-number">${x[0]}</div><h4>${x[1]}</h4><p class="small">${x[2]}</p></div>`).join('')}</div>`;}
function renderRoleplay(){const r=roles[ui.role],clock=practiceClock();return `${pageHead(9,'Role-play & communication practice','One plays the applicant; the other reads the actor brief privately. Swap roles.')}
 <div class="split"><aside class="card sidebar-card"><h3>Choose a scenario</h3><div class="question-list">${roles.map((x,i)=>`<button class="question-button ${ui.role===i?'active':''}" data-action="role-select" data-i="${i}">${esc(x.title)}</button>`).join('')}</div></aside><div class="stack"><article class="card"><span class="card-label">ROLE-PLAY ${ui.role+1}/${roles.length}</span><h2>${esc(r.title)}</h2><p>${esc(r.brief)}</p>${timingLabel(clock)}${timerBox(clock.speak,clock.read)}${accordion('Actor-only information — keep hidden from applicant',`<p>${esc(r.actor)}</p>`)}</article>${practiceEditor('role-'+ui.role,r.title,'roleplay','Acknowledge emotion, listen with open questions, clarify, explain only within your role, agree a next step and check understanding.')}<div class="card"><h3>Optional recording</h3>${recordingControls()}</div><button class="btn secondary" data-action="role-next">Try another role-play →</button></div></div>`;}


const extendedPractical={
 'Numeracy':[
 {level:1,q:'A clinic had 240 appointments. 15% were cancelled. How many went ahead?',a:'15% of 240 = 36 cancellations. 240 − 36 = 204 appointments went ahead.',steps:'Convert 15% to 0.15 → multiply → subtract from total. Units: appointments.'},
 {level:2,q:'A practice recorded 360 calls in 8 hours. The first three hours had 25 calls/hour. What was the mean hourly rate across the remaining 5 hours?',a:'First 3 hours: 75 calls. Remaining: 360 − 75 = 285. Mean rate = 285 ÷ 5 = 57 calls/hour.',steps:'Identify the relevant total and remove the first period before dividing.'},
 {level:2,q:'Among 450 screening invitations, 62% attended. A further 10% of the attendees needed follow-up. Approximately how many attended and needed follow-up?',a:'Attendance: 450 × 0.62 = 279. Follow-up: 279 × 0.10 = 27.9, approximately 28 people.',steps:'Do not take 10% of all invitations. Use two successive percentages and round people to whole numbers.'},
 {level:3,q:'A clinic had 600 appointments. 20% were telephone, and 25% of the remaining face-to-face appointments were afternoon slots. How many afternoon face-to-face appointments?',a:'Telephone: 120. Face-to-face: 480. Afternoon face-to-face: 0.25 × 480 = 120.',steps:'Use the conditional base (the remaining 480), not the original 600.'},
 {level:3,q:'In a research sample of 800 people, 72 developed a condition. In a comparable group of 1200 people, 84 developed it. Compare absolute risks and their difference.',a:'Risks: 72/800 = 9%; 84/1200 = 7%. Absolute risk difference is 2 percentage points. This alone does not prove the cause of the difference.',steps:'Divide cases by each group size; compare percentages rather than raw case counts.'},
 {level:4,q:'A screening test on 1000 people has 90% sensitivity and 95% specificity. Disease prevalence is 10%. How many true positives, false negatives, false positives and true negatives would you expect?',a:'Disease: 100 → TP = 90, FN = 10. No disease: 900 → TN = 855, FP = 45. Positive results total 135; 90/135 = 66.7% of positive tests would be true positives.',steps:'Split by prevalence first, then sensitivity for diseased and specificity for non-diseased. Expected educational figures only.'},
 {level:4,q:'A hospital’s outpatient attendance rose from 80% of 500 bookings to 84% of 750 bookings. Estimate the increase in attended appointments. Can this alone show better access?',a:'First period = 400 attended; second = 630; increase = 230. Not enough to infer improved access: case mix, booking policies and demand may differ.',steps:'Multiply percentage × denominator in each period; distinguish volume from access or quality.'}
 ],
 'Data interpretation':[
 {level:1,q:'A vaccination programme had uptake of 76%, 81% and 79% in three successive years. Describe the pattern.',a:'Uptake rose by five percentage points, then fell by two; overall it increased by three points. Sample sizes and population changes are unknown.',steps:'Use percentage points for changes between percentages.'},
 {level:2,q:'Clinic A saw 180 patients; 27 reported a delay. Clinic B saw 120; 24 reported a delay. Which had a higher proportion of delays?',a:'Clinic A: 27/180 = 15%. Clinic B: 24/120 = 20%. B had a higher proportion, although A had more delayed patients in raw count.',steps:'Compare rates, not raw numbers.'},
 {level:3,q:'A trial reported a fall in event risk from 12% to 9%. Give the absolute risk reduction, relative risk reduction and number needed to treat.',a:'ARR = 3 percentage points (0.03). RRR = 3/12 = 25%. NNT ≈ 1/0.03 = 33.3, conventionally rounded up to 34. Interpretation depends on study setting and time horizon.',steps:'Use baseline risk as denominator for relative reduction and ARR as decimal for NNT.'},
 {level:4,q:'A new diagnostic test found 84 of 100 ill patients and incorrectly flagged 72 of 900 well patients. Calculate sensitivity, specificity and positive predictive value.',a:'Sensitivity = 84/100 = 84%. Specificity = 828/900 = 92%. PPV = 84/(84+72) ≈ 53.8%. Prevalence affects PPV.',steps:'Build the 2×2 contingency table, then identify the correct denominator for each measure.'}
 ],
 'Prioritisation':[
 {level:1,q:'As a volunteer you are asked for directions while somebody nearby appears faint. What comes first?',a:'Seek immediate help from staff for the possibly unwell person; stay within training, then assist with directions.',steps:'Patient safety and role limits before convenience.'},
 {level:2,q:'You have an urgent deadline, a teammate who needs support and a commitment you cannot meet. How do you respond?',a:'Check what is fixed, communicate early, prioritise work with genuine impact and propose realistic support or rescheduling rather than overpromising.',steps:'Prioritise by urgency, impact and what only you can do.'},
 {level:3,q:'A senior asks you to do a task you have not been trained for while the team is behind schedule. What do you do?',a:'Politely explain your limits, decline to act unsupervised, ask for guidance and offer safer tasks within your training.',steps:'Time pressure does not override safety or competence.'},
 {level:4,q:'A volunteer notices a visitor struggling to breathe, a worried relative requesting information and a queue forming at reception. Rank the immediate actions and explain your limits.',a:'Alert clinically trained staff/emergency help for the visitor immediately. You should not independently diagnose or provide treatment beyond your training. Ask colleagues to support the relative and reception queue.',steps:'Recognise potential urgency, escalate, delegate appropriately and communicate.'}
 ],
 'Instruction challenge':[
 {level:1,q:'Explain how to draw a 3×3 grid with a circle in its top-right cell.',a:'Give an unambiguous orientation, divide into rows and columns, identify row 1 column 3 and ask for confirmation.',steps:'Use plain sequential instructions and check understanding.'},
 {level:2,q:'Describe a simple pattern with three shapes while your partner cannot see the source.',a:'Agree axes/orientation, go shape by shape, use measurable relative positions and ask for a teach-back.',steps:'Communication depends on checking interpretation.'},
 {level:3,q:'Your partner misinterprets an instruction halfway through a timed pattern task. Recover without blaming them.',a:'Pause, acknowledge the ambiguity, confirm the current position, clarify one step at a time and check the result.',steps:'Adapt instructions instead of repeating the same phrase louder.'},
 {level:4,q:'Explain an unfamiliar five-stage process to a partner with limited time and uncertain vocabulary.',a:'Clarify starting knowledge, identify essential steps, choose everyday terms, chunk information, invite questions and use teach-back.',steps:'Prioritise accuracy and understanding over speed.'}
 ]
};

function dataPreview(){const vals=[{name:'Clinic A',value:64},{name:'Clinic B',value:78},{name:'Clinic C',value:71}];return `<div class="mini-chart"><div class="micro">ILLUSTRATIVE DATA · Example appointment completion (%)</div><div class="chart-bars">${vals.map(x=>`<div class="bar-col"><b>${x.value}%</b><div class="bar" style="height:${x.value}px"></div><div class="bar-label">${x.name}</div></div>`).join('')}</div><p class="micro">Compare percentages, but ask about denominators and case mix before drawing conclusions.</p></div>`;}
function renderPractical(){const types=Object.keys(extendedPractical);if(!types.includes(ui.practicalTab))ui.practicalTab=types[0];const eligible=extendedPractical[ui.practicalTab].filter(x=>x.level===ui.practicalLevel);const item=eligible[ui.practicalIndex%eligible.length]||eligible[0];const clock=practiceClock();return `${pageHead(10,'Unfamiliar & practical stations','Multi-step reasoning, real data literacy and clear explanations under pressure.')}
 <div class="tabbar">${types.map(x=>`<button data-action="practical-tab" data-tab="${x}" class="${ui.practicalTab===x?'active':''}">${x}</button>`).join('')}</div>
 <div class="pills" style="margin:15px 0">${[['1','Foundation'],['2','Intermediate'],['3','Advanced'],['4','Interview Challenge']].map(([n,name])=>`<button class="pill ${Number(n)===ui.practicalLevel?'active':''}" data-action="practical-level" data-level="${n}">${name}</button>`).join('')}</div>
 <div class="grid two"><article class="card"><span class="card-label">${ui.practicalTab} · LEVEL ${ui.practicalLevel}</span><h2 style="font-size:27px">${esc(item.q)}</h2>${ui.practicalTab==='Data interpretation'?dataPreview():''}${timingLabel(clock)}${timerBox(clock.speak,clock.read)}<div class="actions"><button class="btn secondary" data-action="practical-next">Next challenge →</button></div></article><article class="card"><h3>Worked solution</h3>${accordion('Reveal method, answer & interpretation',`<h4>Reasoning</h4><p>${esc(item.steps)}</p><h4>Solution</h4><p>${esc(item.a)}</p><p class="micro">If you arrived at a different value, compare your setup, denominator, units and rounding.</p>`)}<p class="micro">Interview challenge: explain your calculation aloud, including why other information is not enough.</p></article></div>
 ${practiceEditor(`practical-${ui.practicalTab}-${ui.practicalLevel}-${eligible.indexOf(item)}`,item.q,'practical',item.a+' Method: '+item.steps)}
 <div class="note">Numbers and healthcare contexts here are fictional practice data, not clinical instructions. Competence is about transparent reasoning, not medical treatment calculations.</div>`;}

function timedBank(){const p=ui.timedCategory;let out=questions.map(q=>({q:q.q,guide:q.guide,tag:q.category}));if(p==='Ethics')out=dilemmas.map(q=>({q:q[0],guide:q[1],tag:'Ethics scenario'}));if(p==='Universities')out=unis[ui.uni].questions.map(q=>({q,guide:'Explain your reasoning, use a clear structure, demonstrate insight and connect your answer to the university when relevant.',tag:ui.uni}));if(p==='NHS & news')out=news.map(n=>({q:`Discuss: ${n.title}. What should the NHS prioritise?`,guide:`Explain ${n.detail} Consider patient impact: ${n.why} Debate: ${n.debate}`,tag:'NHS / news'}));if(p!=='All'&&p!=='Ethics'&&p!=='Universities'&&p!=='NHS & news')out=out.filter(q=>q.tag===p);return out;}
function renderTimed(){let t=ui.timedQuestion,kind=t?classify(t.q,t.tag):'personal',clock=ui.timedCategory==='Universities'?uniTiming[ui.uni]:practiceClock();return `${pageHead(11,'Timed MMI practice','Get an unfamiliar question, answer aloud and mark the attempt against clear criteria.')}
 <div class="grid two"><div class="card"><div class="field"><label>Question type</label><select class="input" data-action="timed-category">${['All',...questionGroups.map(g=>g.name),'Ethics','NHS & news','Universities'].map(c=>`<option ${ui.timedCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>University</label><select class="input" data-action="timed-uni">${Object.keys(unis).map(c=>`<option ${ui.uni===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="actions"><button class="btn" data-action="timed-random">Draw a question</button><button class="btn secondary" data-action="timed-retry">Reset practice</button></div><div class="divider"></div><div class="card-label">${t?esc(t.tag):'DRAW YOUR FIRST QUESTION'}</div><h2 style="font-size:28px">${t?esc(t.q):'Select a category, then draw a question.'}</h2><p class="micro">Read once, make two or three points, and answer without a script.</p></div>
 <div class="card"><div class="kicker">INTERVIEW CLOCK</div>${timingLabel(clock)}${timerBox(clock.speak,clock.read)}</div></div>
 ${t?`<div class="section-title"><h2>Review your attempt</h2></div>${practiceEditor('timed-'+(ui.timedCategory==='Universities'?ui.uni+'-':'')+t.q,t.q,kind,t.guide)}<div class="card"><h3>Optional recording</h3><p class="micro">Record your spoken answer with permission from anyone in the room. Recordings are uploaded to your private Supabase bucket and visible to both approved accounts.</p>${recordingControls()}</div>`:''}`;}

const mockCfg={'General MMI':{count:6,mins:5,read:1},Leicester:{count:7,mins:9,read:1},Nottingham:{count:6,mins:5,read:0},Leeds:{count:6,mins:7,read:1},Keele:{count:2,mins:15,read:0},Liverpool:{count:6,mins:7,read:1},Plymouth:{count:6,mins:7,read:1}};
function getMockPrompts(school){let pool=[];
 const motivation=questions.filter(x=>x.category==='Motivation & the profession'||x.category==='Experience & reflection').map(x=>({title:'Personal insight',q:x.q,guide:x.guide}));
 const ethics=dilemmas.map(x=>({title:'Ethical judgement',q:x[0],guide:x[1]}));
 const role=roles.map(x=>({title:'Communication scenario',q:x.brief,guide:x.assess}));
 const other=questions.filter(x=>x.category==='Teamwork & leadership'||x.category==='Self-awareness & resilience').map(x=>({title:'Personal qualities',q:x.q,guide:x.guide}));
 const nhs=news.map(x=>({title:'NHS discussion',q:x.debate,guide:x.detail}));
 const uni=unis[school]?.questions.map(q=>({title:`${school}-style practice`,q,guide:'Think aloud, give evidence, recognise uncertainty and reflect.'}))||[];
 const cats=[motivation,ethics,role,other,nhs,uni.length?uni:motivation,ethics,role];
 let n=mockCfg[school].count;for(let i=0;i<n;i++){const a=cats[i%cats.length];pool.push(a[Math.floor(Math.random()*a.length)]);}return pool;
}
function renderMocks(){const m=ui.mock,opt=Object.keys(mockCfg),cfg=mockCfg[ui.mockSchool];const mockClock=ui.mockSchool==='General MMI'?practiceClock():uniTiming[ui.mockSchool];return `${pageHead(12,'Full mock interview simulator','One person answers, the other asks follow-ups and records evidence-based feedback.')}
 ${!m?`<div class="grid two"><article class="card"><span class="card-label">SET UP YOUR MOCK</span><div class="field"><label>Interview style</label><select class="input" data-action="mock-school">${opt.map(x=>`<option ${ui.mockSchool===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Candidate</label>${personPick()}</div>${timingLabel(mockClock)}<p class="micro">${cfg.count} stations/conversations. Format is a rehearsal approximation unless the university has published it.</p><button class="btn" data-action="mock-start" ${!canEdit()?'disabled':''}>Begin mock →</button></article><article class="card pink"><h3>Examiner instructions</h3><p>Ask the prompt exactly, then follow up where it is vague. Record what the candidate actually said, using the tailored marking guidance. Do not give marks for implied knowledge or enthusiasm alone.</p><p class="micro">Each mock is partner/self-assessed, not AI-marked. Paused progress is saved as a draft.</p></article></div>`:
 m.finished?`<div class="card pink"><h2>Mock complete · ${esc(m.person)}</h2><p>Practice average: <b>${m.total}/10</b> across ${m.results.length} stations.</p>${m.results.map((r,i)=>`<div class="entry-card"><b>Station ${i+1}: ${esc(m.stations[i].title)}</b><p>${(Number(r.score)*6).toFixed(0)}/30 · ${esc(r.note||'No note')}</p></div>`).join('')}<div class="actions"><a class="button" href="#tracking">Open progress</a><button class="btn secondary" data-action="mock-new">New mock</button></div></div>`:
 `<div class="grid two"><article class="card"><span class="card-label">${esc(m.school)} · STATION ${m.index+1} / ${m.stations.length}</span><h2>${esc(m.stations[m.index].q)}</h2><p class="micro">The examiner guidance stays hidden until the candidate finishes.</p>${markingGuide(m.stations[m.index].q,m.stations[m.index].guide,classify(m.stations[m.index].q,m.stations[m.index].title))}</article><div class="stack"><div class="card">${timingLabel(m.school==='General MMI'?practiceClock():uniTiming[m.school])}${timerBox(mockCfg[m.school].mins*60,mockCfg[m.school].read*60)}</div><div class="card"><h3>Examiner notes</h3><div class="field"><label>Question-specific marks (out of 30)</label><div class="score-grid">${(markProfiles[classify(m.stations[m.index].q,m.stations[m.index].title)]||markProfiles.personal).map(c=>`<div class="field"><label>${esc(c[0])} / ${c[1]}</label><select class="input mock-score-part" data-max="${c[1]}">${Array.from({length:c[1]+1},(_,n)=>`<option value="${n}">${n}</option>`).join('')}</select></div>`).join('')}</div></div><div class="field"><label>One strength + one actionable improvement</label><textarea id="mock-note" class="input" rows="3" placeholder="Specific evidence and what to try next"></textarea></div>${recordingControls()}<button class="btn" data-action="mock-next">${m.index===m.stations.length-1?'Finish and save mock':'Save station and continue →'}</button><p class="micro">Station draft saves locally and to cloud when you continue.</p></div></div></div>`}
 ${!m?sourceBox([['https://www.medschools.ac.uk/for-students/applying-to-medical-school/interviews/','MSC interview guidance']]):''}`;}

function renderTracking(){let scores=db.scores[ui.person].slice().sort((a,b)=>new Date(a.date)-new Date(b.date)),notes=db.notes[ui.person],recent=scores.slice(-8),avg=scores.length?(scores.reduce((s,x)=>s+Number(x.score),0)/scores.length).toFixed(1):'—';return `${pageHead(13,'Feedback, notes & performance tracking','Track what is actually improving. Keep separate records for Eli and Habibti, and make the next practice session targeted.')}
 <div class="flex-between" style="margin-bottom:16px"><div class="kicker">PERSONAL DASHBOARD</div>${personPick()}</div>
 <div class="grid three"><div class="card soft"><div class="stat">${scores.length}</div><p>Practice sessions logged</p></div><div class="card soft"><div class="stat">${avg}</div><p>Average practice score / 10</p></div><div class="card soft"><div class="stat">${notes.length}</div><p>Personal notes and targets</p></div></div>
 ${section('Performance over time','Practice rubric only — not a university grading scale.')}
 <div class="card"><div class="flex-between"><h3>Recent session scores</h3><span class="tag">Out of 10</span></div>${recent.length?`<div class="chart-bars">${recent.map((x,i)=>`<div class="bar-col"><strong class="small">${Number(x.score).toFixed(1)}</strong><div class="bar" style="height:${Math.max(4,10*Number(x.score))}px"></div><div class="bar-label">${fmtDate(x.date).split(' ').slice(0,2).join(' ')}</div></div>`).join('')}</div>`:`<div class="empty">Your chart will appear after your first scored practice.</div>`}</div>
 ${section('Add a feedback record')}
 <div class="grid two"><div class="card"><form id="score-form"><div class="fieldrow"><div class="field"><label>Date</label><input class="input" name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Type</label><select class="input" name="type"><option>Timed MMI</option><option>Full mock</option><option>Role-play</option><option>Ethics</option><option>Numeracy</option><option>Other practice</option></select></div></div><div class="fieldrow" style="margin-top:10px"><div class="field"><label>Rehearsal score (0–10)</label><input class="input" name="score" type="number" min="0" max="10" step="0.5" value="7" required></div><div class="field"><label>What was the focus?</label><input class="input" name="focus" maxlength="85" placeholder="e.g. empathy, Leicester MMI"></div></div><div class="field" style="margin-top:10px"><label>Strength</label><textarea class="input" name="strength" rows="2" placeholder="What went well?"></textarea></div><div class="field" style="margin-top:10px"><label>One improvement for next time</label><textarea class="input" name="improve" rows="2" required placeholder="Be more specific than 'speak better'."></textarea></div><div class="actions"><button class="btn" type="submit">Save feedback</button></div></form></div>
 <div class="card"><h3>Previous feedback</h3><div class="list-rows">${scores.length?scores.slice().reverse().map(s=>`<div class="entry-card"><div class="flex-between"><strong>${esc(s.type)} · ${Number(s.score).toFixed(1)}/10</strong><button class="btn ghost sm" data-action="score-delete" data-id="${esc(s.id)}">Delete</button></div><div class="meta">${fmtDate(s.date)} · ${esc(s.focus||'General')}</div>${s.strength?`<p class="small"><strong>Worked:</strong> ${esc(s.strength)}</p>`:''}<p class="small"><strong>Next:</strong> ${esc(s.improve||'No note')}</p></div>`).join(''):`<div class="empty">No scores yet. Record a mock or practice station.</div>`}</div></div></div>
 ${section('Notes & personal targets')}
 <div class="grid two"><div class="card"><form id="note-form"><div class="field"><label>Note title</label><input name="title" class="input" required maxlength="100" placeholder="e.g. Stop rushing ethical conclusions"></div><div class="field" style="margin-top:10px"><label>Notes</label><textarea name="body" class="input" rows="4" required placeholder="What needs changing? What's the plan?"></textarea></div><div class="actions"><button type="submit" class="btn">Save note</button></div></form></div><div class="card"><h3>${ui.person}'s saved notes</h3><div class="list-rows">${notes.length?notes.slice().reverse().map(n=>`<div class="entry-card"><div class="flex-between"><h4>${esc(n.title)}</h4><button class="btn ghost sm" data-action="note-delete" data-id="${esc(n.id)}">Delete</button></div><div class="entry-body">${esc(n.body)}</div></div>`).join(''):`<div class="empty">Keep your next practice target here.</div>`}</div></div></div>
 ${section('Cloud files & recordings')}
 <div class="grid two"><article class="card"><h3>Upload a practice file</h3><p class="micro">PDF, image, text or audio, up to 12 MB. Do not upload confidential patient information. Uploaded files can be viewed by both approved accounts.</p><input class="input" type="file" id="cloud-file" ${!canEdit()?'disabled':''} accept=".pdf,.jpg,.jpeg,.png,.txt,.webm,.mp3,.wav,.m4a,audio/*"><button class="btn" data-action="file-upload" ${!canEdit()?'disabled':''}>Upload file</button><p id="upload-message" class="micro"></p></article><article class="card"><h3>${ui.person}'s files</h3><div class="list-rows">${(db.uploads[ui.person]||[]).length?db.uploads[ui.person].map(f=>`<div class="entry-card"><b>${esc(f.filename)}</b><div class="actions"><button class="btn sm secondary" data-action="file-open" data-path="${esc(f.path)}">Open securely</button>${canEdit()?`<button class="btn sm ghost" data-action="file-delete" data-path="${esc(f.path)}">Delete</button>`:''}</div></div>`).join(''):'<p class="micro">No files uploaded yet.</p>'}</div></article></div>
 ${section('Back up your work')}
 <article class="card soft"><p>Signed-in edits save automatically to Supabase. A device copy is kept temporarily if the internet drops. Download a JSON backup whenever you want an extra personal copy. Importing old backups requires reviewing which account will own the entries.</p><div class="actions"><button class="btn" data-action="export">Export JSON backup</button><button class="btn secondary" data-action="import">Import a backup</button><input id="backup-file" type="file" accept=".json,application/json" class="hide"></div><p class="micro">Cloud storage must be tested on the live site before relying on it as your only copy.</p></article>`;}
function render(){let page=location.hash.replace('#','')||'home';if(!navNames[page])page='home';if(page!==ui.page){resetTimer();ui.page=page;window.scrollTo({top:0,behavior:'instant'});}const renderers={home:renderHome,universities:renderUniversities,structures:renderStructures,common:renderCommon,reflections:renderReflections,ethics:renderEthics,nhs:renderNHS,news:renderNews,roleplay:renderRoleplay,practical:renderPractical,timed:renderTimed,mocks:renderMocks,tracking:renderTracking};$('#app').innerHTML=(!cloud.user&&['common','reflections','tracking','mocks'].includes(page))?authNotice():renderers[page]();if(cloud.user&&!canEdit())$$('#reflection-form input,#reflection-form textarea,#reflection-form select,#reflection-form button,#score-form input,#score-form textarea,#score-form select,#score-form button,#note-form input,#note-form textarea,#note-form button,#common-answer,[data-action="reflection-edit"],[data-action="reflection-delete"],[data-action="note-delete"],[data-action="score-delete"]') .forEach(el=>el.disabled=true);$$('#main-nav a').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main-nav').classList.remove('is-open');$('#nav-toggle').setAttribute('aria-expanded','false');document.title=`${navNames[page]} | DiorInterviews`;repaintTimers();}
function refresh(){render();}
const id=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
function removeData(type,key){if(!canEdit())return;if(!confirm('Delete this saved entry?'))return;db[type][ui.person]=db[type][ui.person].filter(x=>x.id!==key);persist();refresh();toast('Entry deleted.');}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='show-login'){authModal(true);return;}
 else if(a==='ethic-select'){ui.ethic=Number(b.dataset.i);resetTimer();refresh();return;}
 else if(a==='practical-level'){ui.practicalLevel=Number(b.dataset.level);ui.practicalIndex=0;resetTimer();refresh();return;}
 else if(a==='practice-score-open'){let key=b.dataset.key;let target=document.getElementById('score-box-'+encodeURIComponent(key));if(!target){toast('Marking panel unavailable');return;}target.innerHTML=scoreInterface(key,ui.page==='ethics'?dilemmas[ui.ethic][0]:ui.page==='practical'?extendedPractical[ui.practicalTab].filter(x=>x.level===ui.practicalLevel)[ui.practicalIndex%extendedPractical[ui.practicalTab].filter(x=>x.level===ui.practicalLevel).length].q:ui.page==='roleplay'?roles[ui.role].title:ui.timedQuestion?.q||'',ui.page==='ethics'?'ethics':ui.page==='roleplay'?'roleplay':ui.page==='practical'?'practical':classify(ui.timedQuestion?.q||''));target.hidden=!target.hidden;return;}
 else if(a==='practice-score-save'){if(!canEdit()){toast('Sign in to save your score.');return;}const box=b.closest('.score-editor');const fields=$$('.score-criterion',box);const total=fields.reduce((sum,x)=>sum+Number(x.value),0);const result={id:id(),date:new Date().toISOString().slice(0,10),type:ui.page==='practical'?'Numeracy / practical':ui.page==='ethics'?'Ethical reasoning':ui.page==='roleplay'?'Role-play':'Timed MMI',score:Number((total/3).toFixed(1)),focus:b.dataset.key,strength:$('#mark-strength')?.value.trim()||'',improve:$('#mark-improve')?.value.trim()||'Review the lowest scoring criterion and try again.',marks:fields.map(x=>Number(x.value)),outOf:30};db.scores[me()].push(result);db.practice[me()][b.dataset.key]??={};db.practice[me()][b.dataset.key].lastScore=result;persist();toast('Human-assessed rubric saved to cloud queue.');refresh();return;}
 else if(a==='file-upload'){awaitUpload();return;}
 else if(a==='file-open'){openCloudFile(b.dataset.path);return;}
 else if(a==='file-delete'){deleteCloudFile(b.dataset.path);return;}
 else if(a==='audio-start'){startAudio();return;}
 else if(a==='audio-stop'){stopAudio();return;}
 else if(a==='person'){ui.person=b.dataset.person;ui.editingReflection=null;refresh();}
 else if(a==='uni'){ui.uni=b.dataset.uni;refresh();}
 else if(a==='uni-to-timed'){let p=unis[ui.uni].questions[Number(b.dataset.q)];ui.timedCategory='Universities';ui.timedQuestion={q:p,guide:'Explain a clear position, use a specific example or balanced reasoning and reflect on why this medical school values the skill.',tag:ui.uni};resetTimer();location.hash='timed';refresh();}
 else if(a==='question'){ui.q=Number(b.dataset.q);refresh();}
 else if(a==='common-timer'){ui.timedQuestion={...questions[ui.q],tag:questions[ui.q].category};ui.timedCategory=questions[ui.q].category;resetTimer();location.hash='timed';refresh();}
 else if(a==='plan-check'){}
 else if(a==='reflection-edit'){ui.editingReflection=b.dataset.id;refresh();window.scrollTo({top:230,behavior:'smooth'});}
 else if(a==='reflection-delete'){removeData('reflections',b.dataset.id);}
 else if(a==='reflection-cancel'){ui.editingReflection=null;refresh();}
 else if(a==='note-delete'){removeData('notes',b.dataset.id);}
 else if(a==='score-delete'){removeData('scores',b.dataset.id);}
 else if(a==='role-select'){ui.role=Number(b.dataset.i);resetTimer();refresh();}
 else if(a==='role-next'){ui.role=(ui.role+1)%roles.length;resetTimer();refresh();}
 else if(a==='practical-tab'){ui.practicalTab=b.dataset.tab;ui.practicalIndex=0;resetTimer();refresh();}
 else if(a==='practical-next'){ui.practicalIndex++;resetTimer();refresh();}
 else if(a==='practical-random'){ui.practicalIndex=0;resetTimer();refresh();}
 else if(a==='timer-preset'){timerSet(Number(b.dataset.secs));}
 else if(a==='timer-go'){if(timer.total===0){let el=$('.js-timer-panel');let def=Number(el?.dataset.preset||300);timerSet(def,Number(el?.dataset.read||0));}timerStart();}
 else if(a==='timer-pause'){timerPause();}
 else if(a==='timer-reset'){timerSet(Number(b.dataset.secs),Number(b.dataset.read||0));}
 else if(a==='timed-random'){let bank=timedBank();if(!bank.length)return;let opts=bank.filter(q=>q.q!==ui.timedQuestion?.q);ui.timedQuestion=(opts.length?opts:bank)[Math.floor(Math.random()*(opts.length||bank.length))];resetTimer();refresh();}
 else if(a==='timed-retry'){resetTimer();refresh();}
 else if(a==='mock-start'){if(!canEdit())return;ui.mock={school:ui.mockSchool,person:ui.person,index:0,stations:getMockPrompts(ui.mockSchool),results:[],finished:false};db.mocks[ui.person]=[ui.mock];persist();resetTimer();refresh();}
 else if(a==='mock-next'){const m=ui.mock;if(!m||!canEdit())return;const parts=$$('.mock-score-part').map(el=>Number(el.value));const raw=parts.reduce((a,b)=>a+b,0);const value=Number((raw/6).toFixed(2));const note=$('#mock-note')?.value?.trim()||'';m.results.push({score:value,marks:parts,outOf:30,note});if(m.index===m.stations.length-1){m.finished=true;m.total=Number((m.results.reduce((sum,r)=>sum+r.score,0)*2/m.results.length).toFixed(1));db.scores[m.person].push({id:id(),date:new Date().toISOString().slice(0,10),type:`${m.school} full mock`,score:m.total,focus:`${m.results.length}-station circuit`,strength:'Completed the full simulated circuit.',improve:m.results.map((r,i)=>`S${i+1}: ${r.note}`).filter(x=>!x.endsWith(': ')).join(' | ')||'Review weaker stations and repeat.'});persist();toast('Mock results saved to your Progress dashboard.');}else m.index++;db.mocks[m.person]=[m];persist();resetTimer();refresh();}
 else if(a==='mock-new'){if(!canEdit())return;ui.mock=null;db.mocks[ui.person]=[];persist();resetTimer();refresh();}
 else if(a==='export'){const file=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),data:db},null,2)],{type:'application/json'});const url=URL.createObjectURL(file);const linkEl=document.createElement('a');linkEl.href=url;linkEl.download='DiorInterviews-backup.json';document.body.appendChild(linkEl);linkEl.click();linkEl.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Backup downloaded.');}
 else if(a==='import'){$('#backup-file')?.click();}
});
document.addEventListener('change',e=>{
 const el=e.target;if(el.dataset.action==='category'){ui.category=el.value;ui.search='';refresh();}
 if(el.dataset.action==='timed-category'){ui.timedCategory=el.value;ui.timedQuestion=null;resetTimer();refresh();}
 if(el.dataset.action==='timed-uni'){ui.uni=el.value;ui.timedQuestion=null;refresh();}
 if(el.dataset.action==='mock-school'){ui.mockSchool=el.value;refresh();}
 if(el.id==='backup-file'&&el.files?.length){const file=el.files[0];if(file.size>2e6){toast('That backup is too large.');return;}const reader=new FileReader();reader.onload=()=>{try{let obj=JSON.parse(reader.result);let next=obj.data||obj;if(!next||!next.answers||!next.reflections||!next.notes||!next.scores||!next.plan)throw Error('Missing sections');if(!confirm('Import YOUR entries from this backup into your currently signed-in account?'))return;if(!canEdit()){toast('Sign in first.');return;}for(const t of CLOUD_TYPES){if(next[t]?.[me()])db[t][me()]=next[t][me()];}persist();refresh();toast('Your entries imported; syncing to cloud.');}catch{toast('Could not read that DiorInterviews backup.');}};reader.readAsText(file);el.value='';}
});
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.dataset.action==='practice-write'&&canEdit()){const key=el.dataset.key;db.practice[me()][key]??={};db.practice[me()][key].answer=el.value;db.practice[me()][key].updatedAt=new Date().toISOString();persist();}
 if(el.dataset.action==='answer-input'&&canEdit()){db.answers[ui.person][el.dataset.q]=el.value;persist();const state=$('#answer-status');if(state)state.textContent='Saving to cloud…';}
 if(el.dataset.action==='common-search'){ui.search=el.value;const list=$('#common-list');if(list)list.innerHTML=commonList();}
});
document.addEventListener('submit',e=>{
 const form=e.target;
 if(form.id==='reflection-form'){e.preventDefault();if(!canEdit())return;const f=Object.fromEntries(new FormData(form));if(!f.title.trim()||!f.situation.trim()||!f.action.trim()||!f.reflection.trim())return;let list=db.reflections[ui.person];let obj={id:f.id||id(),title:f.title.trim(),type:f.type,situation:f.situation.trim(),action:f.action.trim(),result:f.result.trim(),reflection:f.reflection.trim(),date:new Date().toISOString()};let index=list.findIndex(x=>x.id===obj.id);if(index>=0){obj.date=list[index].date;list[index]=obj;}else list.push(obj);ui.editingReflection=null;persist();refresh();toast('Reflection saved.');}
 if(form.id==='score-form'){e.preventDefault();if(!canEdit())return;const f=Object.fromEntries(new FormData(form));const val=Number(f.score);if(!Number.isFinite(val)||val<0||val>10)return;db.scores[ui.person].push({id:id(),date:f.date,type:f.type,score:val,focus:f.focus.trim(),strength:f.strength.trim(),improve:f.improve.trim()});persist();refresh();toast('Feedback saved.');}
 if(form.id==='note-form'){e.preventDefault();if(!canEdit())return;const f=Object.fromEntries(new FormData(form));if(!f.title.trim()||!f.body.trim())return;db.notes[ui.person].push({id:id(),title:f.title.trim(),body:f.body.trim(),date:new Date().toISOString()});persist();refresh();toast('Note saved.');}
});

function recordingControls(){return `<div class="actions"><button class="btn secondary sm" data-action="audio-start" ${!canEdit()?'disabled':''}>Start audio recording</button><button class="btn ghost sm" data-action="audio-stop" ${!canEdit()?'disabled':''}>Stop & upload</button></div><p class="micro" id="audio-message">Use only with everyone's permission. Browser microphone access and an internet connection are required to upload.</p>`;}
let audioState={recorder:null,stream:null,chunks:[]};
async function startAudio(){if(!canEdit()||audioState.recorder?.state==='recording')return;
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Microphone recording is unavailable in this browser.');return;}
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);audioState={recorder:rec,stream,chunks:[]};rec.ondataavailable=e=>{if(e.data.size)audioState.chunks.push(e.data);};rec.onstop=async()=>{const blob=new Blob(audioState.chunks,{type:rec.mimeType||'audio/webm'});stream.getTracks().forEach(track=>track.stop());if(blob.size>12*1024*1024){toast('Recording over 12 MB — use a shorter clip.');return;}await uploadCloudFile(new File([blob],`MMI-recording-${Date.now()}.webm`,{type:blob.type}));};rec.start();const msg=$('#audio-message');if(msg)msg.textContent='Recording… stop when your answer is finished.';}
 catch(e){toast('Microphone permission was not granted.');}}
function stopAudio(){if(audioState.recorder?.state==='recording'){audioState.recorder.stop();toast('Recording stopped — uploading…');}}
async function uploadCloudFile(file){if(!canEdit()||!cloud.client){toast('Sign in to upload files.');return;}if(!file||file.size>12*1024*1024){toast('Choose a file under 12 MB.');return;}
 const allowed=['application/pdf','image/jpeg','image/png','text/plain','audio/webm','audio/mpeg','audio/mp4','audio/wav','audio/x-wav','audio/ogg'];if(file.type&&!allowed.includes(file.type)){toast('Unsupported file type.');return;}
 const filename=file.name.replace(/[^A-Za-z0-9._-]/g,'-').slice(0,90),path=`${cloud.user.id}/${Date.now()}-${filename}`;
 setSaveStatus('Uploading file…');const {error}=await cloud.client.storage.from('interview-uploads').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(error){console.warn(error);setSaveStatus('Upload failed — try again');toast('File upload failed.');return;}
 db.uploads[me()].push({path,filename:file.name,createdAt:new Date().toISOString(),mime:file.type});persist();toast('Upload complete.');refresh();}
function awaitUpload(){uploadCloudFile($('#cloud-file')?.files?.[0]);}
async function openCloudFile(path){if(!cloud.client||!cloud.user)return;const {data,error}=await cloud.client.storage.from('interview-uploads').createSignedUrl(path,60*10);if(error){toast('Could not access file.');return;}window.open(data.signedUrl,'_blank','noopener');}
async function deleteCloudFile(path){if(!canEdit()||!path.startsWith(cloud.user.id+'/')||!confirm('Delete this uploaded file?'))return;const {error}=await cloud.client.storage.from('interview-uploads').remove([path]);if(error){toast('Could not delete file.');return;}db.uploads[me()]=db.uploads[me()].filter(f=>f.path!==path);persist();refresh();}
$('#auth-toggle').addEventListener('click',async()=>{if(cloud.user){if(confirm('Sign out of DiorInterviews?')){await flushCloud();await cloud.client.auth.signOut();cloud.ready=false;}}else authModal(true);});
$('#auth-close').addEventListener('click',()=>authModal(false));
$('#auth-modal').addEventListener('click',e=>{if(e.target.id==='auth-modal')authModal(false);});
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button');submit.disabled=true;$('#auth-error').textContent='Signing in…';
 try{if(!cloud.client)throw Error('Cloud library unavailable. Check your internet connection.');const {data,error}=await cloud.client.auth.signInWithPassword({email:form.elements.namedItem('email').value.trim(),password:form.elements.namedItem('password').value});if(error)throw error;const name=Object.keys(MEMBERS).find(k=>MEMBERS[k]===data.user.id);if(!name){await cloud.client.auth.signOut();throw Error('This is not an approved DiorInterviews account.');}authModal(false);form.reset();$('#auth-error').textContent='';await handleSession(data.session);}
 catch(err){$('#auth-error').textContent=err.message||'Login failed.';}
 finally{submit.disabled=false;}});
window.addEventListener('online',()=>{if(cloud.user)flushCloud();});
window.addEventListener('beforeunload',e=>{if(cloud.user&&localStorage.getItem(pendingKey(me()))==='1'&&navigator.onLine){e.preventDefault();e.returnValue='';}});

$('#nav-toggle').addEventListener('click',()=>{let nav=$('#main-nav');let v=nav.classList.toggle('is-open');$('#nav-toggle').setAttribute('aria-expanded',String(v));});
window.addEventListener('hashchange',render);
render();
initCloud();
